<?php use App\Support\Security;use App\Support\View;$base='/admin/tournaments/'.(int)$tournament['id'].'/operation';$token=View::e(Security::csrfToken());?>
<main class="admin"><header class="admin-header"><div><span class="eyebrow">Central do campeonato</span><h1><?=View::e($tournament['name'])?></h1><p class="muted">Fluxo assistido para inscricoes, grupos, tabela, partida e homologacao.</p></div><a class="button" href="/admin/tournaments/<?=$tournament['id']?>/configuration">Configurar</a></header>
<section class="panel"><h2>Resumo</h2><div class="stats"><div><b><?=count($teams)?></b><span>Equipes</span></div><div><b><?=count($athletes)?></b><span>Atletas</span></div><div><b><?=count($matches)?></b><span>Partidas</span></div><div><b><?=count(array_filter($matches,fn($m)=>$m['status']==='awaiting_homologation'))?></b><span>Para homologar</span></div></div></section>
<section class="panel"><h2>Inscricoes</h2><form method="post" action="<?=$base?>/registrations" class="form-grid"><input type="hidden" name="_csrf" value="<?=$token?>"><label>Equipe<select required name="team_id"><option value="">Selecione</option><?php foreach($teams as $team):?><option value="<?=$team['id']?>"><?=View::e($team['name'])?></option><?php endforeach;?></select></label><label>Atleta<select required name="person_id"><option value="">Selecione</option><?php foreach($athletes as $a):?><option value="<?=$a['id']?>"><?=View::e($a['full_name'])?></option><?php endforeach;?></select></label><label>Numero<input name="shirt_number" maxlength="3"></label><button class="button">Inscrever atleta</button></form><div class="table-wrap"><table><thead><tr><th>Atleta</th><th>Equipe</th><th>Situacao</th><th>Acao</th></tr></thead><tbody><?php foreach($registrations as $r):?><tr><td><?=View::e($r['full_name'])?></td><td><?=View::e($r['team_name'])?></td><td><?=View::e($r['status'])?></td><td><form method="post" action="<?=$base?>/registrations/review" class="inline-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="registration_id" value="<?=$r['id']?>"><select name="status"><option value="approved">Aprovar</option><option value="pending">Pendencia</option><option value="rejected">Rejeitar</option></select><input name="reason" placeholder="Motivo"><button class="button small">Salvar</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Grupos e tabela</h2><form method="post" action="<?=$base?>/groups" class="form-grid"><input type="hidden" name="_csrf" value="<?=$token?>"><label>Fase<select required name="stage_id"><?php foreach($stages as $s):?><option value="<?=$s['id']?>"><?=View::e($s['name'])?></option><?php endforeach;?></select></label><label>Nome<input required name="name" value="Grupo A"></label><label>Codigo<input required name="code" value="A" maxlength="8"></label><label>Vagas<input required name="max_teams" value="5" type="number" min="2"></label><button class="button">Criar grupo</button></form><?php foreach($groups as $g):?><article class="subpanel"><h3><?=View::e($g['name'])?></h3><form method="post" action="<?=$base?>/groups/assign" class="inline-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="group_id" value="<?=$g['id']?>"><select name="team_id" required><option value="">Adicionar equipe</option><?php foreach($teams as $team):?><option value="<?=$team['id']?>"><?=View::e($team['name'])?></option><?php endforeach;?></select><button class="button small">Adicionar</button></form><form method="post" action="<?=$base?>/schedule" class="inline-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="group_id" value="<?=$g['id']?>"><label>Inicio <input name="start_at" type="datetime-local"></label><button class="button small">Gerar tabela</button></form></article><?php endforeach;?></section>
<section class="panel"><h2>Partidas</h2><div class="table-wrap"><table><thead><tr><th>Confronto</th><th>Fase</th><th>Placar</th><th>Situacao</th><th>Central</th></tr></thead><tbody><?php foreach($matches as $m):?><tr><td><?=View::e($m['home_name'])?> x <?=View::e($m['away_name'])?></td><td><?=View::e($m['stage_name']??'-')?></td><td><?=$m['home_score']??0?> x <?=$m['away_score']??0?></td><td><?=View::e($m['status'])?></td><td><details><summary>Operar partida</summary><form method="post" action="<?=$base?>/events" class="inline-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="match_id" value="<?=$m['id']?>"><select name="team_id"><option value="<?=$m['home_team_id']?>"><?=View::e($m['home_name'])?></option><option value="<?=$m['away_team_id']?>"><?=View::e($m['away_name'])?></option></select><select name="person_id"><option value="">Sem atleta</option><?php foreach($athletes as $a):?><option value="<?=$a['id']?>"><?=View::e($a['full_name'])?></option><?php endforeach;?></select><select name="event_type"><option value="start">Iniciar</option><option value="halftime">Intervalo</option><option value="second_half">Segundo tempo</option><option value="goal">Gol</option><option value="yellow">Amarelo</option><option value="red">Vermelho</option><option value="substitution">Substituicao</option><option value="incident">Ocorrencia</option><option value="end">Encerrar</option></select><input name="minute" type="number" min="0" placeholder="Minuto"><button class="button small">Registrar</button></form><form method="post" action="<?=$base?>/finish" class="inline-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="match_id" value="<?=$m['id']?>"><button class="button small">Finalizar</button></form><form method="post" action="<?=$base?>/homologate" class="inline-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="match_id" value="<?=$m['id']?>"><button class="button small">Homologar</button></form><?php if($m['report_pdf_path']):?><a href="/admin/tournaments/<?=$tournament['id']?>/matches/<?=$m['id']?>/report.pdf">PDF da sumula</a><?php endif;?></details></td></tr><?php endforeach;?></tbody></table></div><form method="post" action="<?=$base?>/knockout"><input type="hidden" name="_csrf" value="<?=$token?>"><button class="button">Gerar mata-mata</button></form></section></main>
